import{_ as e,o as i,c as s,l as a,t as o,N as n}from"./chunks/framework.Bbd9fWQx.js";const f=JSON.parse('{"title":"git-mailinfo | x-cmd man (git man1) | Extracts patch and authorship from a single e-mail\\nmessage","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-mailinfo - Extracts patch and authorship from a single e-mail\\nmessage","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-mailinfo | x-cmd man (git man1) | Extracts patch and authorship from a single e-mail\\nmessage"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-mailinfo - Extracts patch and authorship from a single e-mail\\nmessage"}]]},"headers":[],"params":{"isMan":true,"man":"git-mailinfo","category":"git man1","desc":"Extracts patch and authorship from a single e-mail\\nmessage"},"relativePath":"git/man1/git-mailinfo.md","filePath":"git/man1/git-mailinfo.md"}'),l={name:"git/man1/git-mailinfo.md"},r={class:"visually-hidden"},h=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-mailinfo - Extracts patch and authorship from a single e-mail message</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mailinfo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-k</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-b]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-u </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --encoding</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">encoding</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> -n]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">   [--[no-]scissors] [--quoted-cr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">action</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">   &lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">patc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Reads a single e-mail message from the standard input, and writes the commit log message in &lt;msg&gt; file, and the patches in &lt;patch&gt; file. The author name, e-mail and e-mail subject are written out to the standard output to be used by <em>git am</em> to create a commit. It is usually not necessary to use this command directly. See <strong>git-am</strong>(1) instead.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-k</p><blockquote><p>Usually the program removes email cruft from the Subject: header line to extract the title line for the commit log message. This option prevents this munging, and is most useful when used to read back <em>git format-patch -k</em> output.</p><p>Specifically, the following are removed until none of them remain:</p><blockquote><p>·</p><p>Leading and trailing whitespace.</p></blockquote><blockquote><p>·</p><p>Leading <strong>Re:</strong>, <strong>re:</strong>, and <strong>:</strong>.</p></blockquote><blockquote><p>·</p><p>Leading bracketed strings (between <strong>[</strong> and <strong>]</strong>, usually <strong>[PATCH]</strong>).</p></blockquote><p>Finally, runs of whitespace are normalized to a single ASCII space character.</p></blockquote><p>-b</p><blockquote><p>When -k is not in effect, all leading strings bracketed with <em>[</em> and <em>]</em> pairs are stripped. This option limits the stripping to only the pairs whose bracketed string contains the word &quot;PATCH&quot;.</p></blockquote><p>-u</p><blockquote><p>The commit log message, author name and author email are taken from the e-mail, and after minimally decoding MIME transfer encoding, re-coded in the charset specified by <strong>i18n.commitEncoding</strong> (defaulting to UTF-8) by transliterating them. This used to be optional but now it is the default.</p><p>Note that the patch is always used as-is without charset conversion, even with this flag.</p></blockquote><p>--encoding=&lt;encoding&gt;</p><blockquote><p>Similar to -u. But when re-coding, the charset specified here is used instead of the one specified by <strong>i18n.commitEncoding</strong> or UTF-8.</p></blockquote><p>-n</p><blockquote><p>Disable all charset re-coding of the metadata.</p></blockquote><p>-m, --message-id</p><blockquote><p>Copy the Message-ID header at the end of the commit message. This is useful in order to associate commits with mailing list discussions.</p></blockquote><p>--scissors</p><blockquote><p>Remove everything in body before a scissors line (e.g. &quot;-- &gt;8 --&quot;). The line represents scissors and perforation marks, and is used to request the reader to cut the message at that line. If that line appears in the body of the message before the patch, everything before it (including the scissors line itself) is ignored when this option is used.</p><p>This is useful if you want to begin your message in a discussion thread with comments and suggestions on the message you are responding to, and to conclude it with a patch submission, separating the discussion and the beginning of the proposed commit log message with a scissors line.</p><p>This can be enabled by default with the configuration option mailinfo.scissors.</p></blockquote><p>--no-scissors</p><blockquote><p>Ignore scissors lines. Useful for overriding mailinfo.scissors settings.</p></blockquote><p>--quoted-cr=&lt;action&gt;</p><blockquote><p>Action when processes email messages sent with base64 or quoted-printable encoding, and the decoded lines end with a CRLF instead of a simple LF.</p><p>The valid actions are:</p><blockquote><p>·</p><p><strong>nowarn</strong>: Git will do nothing when such a CRLF is found.</p></blockquote><blockquote><p>·</p><p><strong>warn</strong>: Git will issue a warning for each message if such a CRLF is found.</p></blockquote><blockquote><p>·</p><p><strong>strip</strong>: Git will convert those CRLF to LF.</p></blockquote><p>The default action could be set by configuration option <strong>mailinfo.quotedCR</strong>. If no such configuration option has been set, <strong>warn</strong> will be used.</p></blockquote><p>&lt;msg&gt;</p><blockquote><p>The commit log message extracted from e-mail, usually except the title line which comes from e-mail Subject.</p></blockquote><p>&lt;patch&gt;</p><blockquote><p>The patch extracted from e-mail.</p></blockquote><h2 id="configuration" tabindex="-1">CONFIGURATION <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;CONFIGURATION&quot;">​</a></h2><p>Everything below this line in this section is selectively included from the <strong>git-config</strong>(1) documentation. The content is the same as what&#39;s found there:</p><p>mailinfo.scissors</p><blockquote><p>If true, makes <strong>git-mailinfo</strong>(1) (and therefore <strong>git-am</strong>(1)) act by default as if the --scissors option was provided on the command-line. When active, this features removes everything from the message body before a scissors line (i.e. consisting mainly of &quot;&gt;8&quot;, &quot;8&lt;&quot; and &quot;-&quot;).</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,35);function p(t,c,g,d,m,u){return i(),s("div",null,[a("h1",r,o(t.$params.man),1),h])}const b=e(l,[["render",p]]);export{f as __pageData,b as default};
